/// <returns>inserted bvnr</returns>
public NDXRicoKalkBVNr insertKalkBVKopf(NDXRicoKalkBVNr _bvnr, boolean _displayOnConsole = true, str _textToDisplayOnConsole = '')
{
    NDXRicoKalkBVNr bvnr;
    maintainRelayContract.GeneratedDateTime = DateTimeUtil::applyTimeZoneOffset(DateTimeUtil::utcNow(), DateTimeUtil::getUserPreferredTimeZone());

    azureRelaySender = new AzureRelaySenderRicoKalk(keyVaultGetSecretRelay);

    KalkBVKopf kalkBVKopf = maintainRelayContract.KalkBVKopf;
    kalkBVKopf.SelectValue = NDXSqlConstants::SQLSelect;
    kalkBVKopf.SelectValue += strFmt(NDXSqlConstants::SQLPlaceholder, NDXRicoKalkTblKalkBVKopfConstants::BVNr);
    kalkBVKopf.SelectValue += strFmt(NDXSqlConstants::SQLFromWhere, kalkBVKopf.TableName);
    kalkBVKopf.SelectValue += strFmt(NDXSqlConstants::SQLFieldEqualInt, NDXRicoKalkTblKalkBVKopfConstants::BVNr, _bvnr);
    kalkBVKopf.addSqlFieldWithValueInt(NDXRicoKalkTblKalkBVKopfConstants::BVNr, _bvnr);
    kalkBVKopf.SQLCRUD = SQLCRUD::Insert;

    maintainRelayContract.ServiceActionInfo = strFmt(NDXPlaceholderConstants::FirstInSquareBrackets2, this.SQLCRUD2String(kalkBVKopf.SQLCRUD), kalkBVKopf.SelectValue);
    maintainRelayContract.DisplayOnConsole = _displayOnConsole;
    maintainRelayContract.TextToDisplayOnConsole = _textToDisplayOnConsole;
    this.incrementInsertOperation();
    this.addOperationHistory(maintainRelayContract.ServiceActionInfo);
    azureRelaySender.fillRequest(maintainRelayContract);
    HttpResponseMessage response = azureRelaySender.SendMessage().GetAwaiter().GetResult();
    if (response.IsSuccessStatusCode && response.StatusCode != System.Net.HttpStatusCode::Conflict)
    {
        responseContract = azureRelaySender.contractFromResponseMessage(response) as IRicoKalkMaintainRelayResponseContract;

        IEnumerable enumerableList = responseContract.TblKalkBVKopfList;
        IEnumerator enumeratorList = enumerableList.GetEnumerator();
        while (enumeratorList.MoveNext())
        {
            TblKalkBVKopf tblKalkBVKopf = enumeratorList.Current;
            bvnr = tblKalkBVKopf.BVNr;
        }
    }
    else
    {
        throw Error(response.ReasonPhrase);
    }
    return bvnr;
}

