 public NDXRicoPreisListeId getRicoPreisListId(NDXRicoIntId _intId, boolean _displayOnConsole = true, str _textToDisplayOnConsole = '')
 {
     IEnumerable enumerableList;
     IEnumerator enumeratorList;
     NDXRicoPreisListeId priceListId = 0;
     maintainRelayContract = ado.RicoKalkMaintainRelayContract.Initialize();
     NDXRicoKalkADO::initMaintainRelayContract(maintainRelayContract);

