     KalkInterressent kalkInterressent = maintainRelayContract.KalkInterressent;
     kalkInterressent.SelectValue = NDXSqlConstants::SQLSelect;
     kalkInterressent.SelectValue += strFmt(NDXSqlConstants::SQLPlaceholderComma, NDXRicoKalkTblKalkInterressentConstants::Preisliste_IDBOUND);
     kalkInterressent.SelectValue += strFmt(NDXSqlConstants::SQLPlaceholderComma, NDXRicoKalkTblKalkInterressentConstants::KonditKunde);
     kalkInterressent.SelectValue += strFmt(NDXSqlConstants::SQLPlaceholder, NDXRicoKalkTblKalkInterressentConstants::Knr);
     kalkInterressent.SelectValue += strFmt(NDXSqlConstants::SQLFromWhere, kalkInterressent.TableName);
     kalkInterressent.SelectValue += strFmt(NDXSqlConstants::SQLFieldEqualInt, NDXRicoKalkTblKalkInterressentConstants::Int_id, _intId);
     kalkInterressent.SQLCRUD = SQLCRUD::Select;

     maintainRelayContract.ServiceActionInfo = strFmt(NDXPlaceholderConstants::FirstInSquareBrackets2, this.SQLCRUD2String(kalkInterressent.SQLCRUD), kalkInterressent.SelectValue);
     maintainRelayContract.DisplayOnConsole = _displayOnConsole;
