     if (response.IsSuccessStatusCode && response.StatusCode != System.Net.HttpStatusCode::Conflict)
     {
         responseContract = azureRelaySender.contractFromResponseMessage(response) as IRicoKalkMaintainRelayResponseContract;

         enumerableList = responseContract.TblKalkInterressentList;
         enumeratorList = enumerableList.GetEnumerator();
         while (enumeratorList.MoveNext())
         {
             TblKalkInterressent tblKalkInterressent  = enumeratorList.Current;
             int priceListFrom = tblKalkInterressent.KonditKunde ? tblKalkInterressent.KonditKunde : tblKalkInterressent.Knr;
             if (priceListFrom)
             {
                 maintainRelayContract = ado.RicoKalkMaintainRelayContract.Initialize();
                 NDXRicoKalkADO::initMaintainRelayContract(maintainRelayContract);

                 azureRelaySender = new AzureRelaySenderRicoKalk(keyVaultGetSecretRelay);

                 Kunde kunde = maintainRelayContract.Kunde;
                 kunde.SelectValue = NDXSqlConstants::SQLSelect;
                 kunde.SelectValue += strFmt(NDXSqlConstants::SQLPlaceholder, NDXRicoKalkTblKundeConstants::Preisliste);
                 kunde.SelectValue += strFmt(NDXSqlConstants::SQLFromWhere, kunde.TableName);
                 kunde.SelectValue += strFmt(NDXSqlConstants::SQLFieldEqualInt, NDXRicoKalkTblKundeConstants::Knr, priceListFrom);
                 kunde.SQLCRUD = SQLCRUD::Select;

                 maintainRelayContract.ServiceActionInfo = strFmt(NDXPlaceholderConstants::FirstInSquareBrackets2, this.SQLCRUD2String(kunde.SQLCRUD), kunde.SelectValue);
