                             kalkSonstKz.SelectValue += strFmt(NDXSqlConstants::SQLPlaceholderComma, NDXRicoKalkTblKalkSonstKzConstants::KZ);
                             kalkSonstKz.SelectValue += strFmt(NDXSqlConstants::SQLPlaceholder, NDXRicoKalkTblKalkSonstKzConstants::KZ_ID);
                             kalkSonstKz.SelectValue += strFmt(NDXSqlConstants::SQLFromWhere, kalkSonstKz.TableName);
                             kalkSonstKz.SelectValue += strFmt(NDXSqlConstants::SQLFieldEqualInt, NDXRicoKalkTblKalkSonstKzConstants::Bereich, NDXRicoKalkTblKalkSonstKzConstants::BereichPreisliste);
                             kalkSonstKz.SelectValue += strFmt(NDXSqlConstants::SQLAndFieldEqualStr, NDXRicoKalkTblKalkSonstKzConstants::KZ, tblKunde.Preisliste);
                             kalkSonstKz.SQLCRUD = SQLCRUD::Select;

                             maintainRelayContract.ServiceActionInfo = strFmt(NDXPlaceholderConstants::FirstInSquareBrackets2, this.SQLCRUD2String(kunde.SQLCRUD), kunde.SelectValue);
                             maintainRelayContract.DisplayOnConsole = _displayOnConsole;
                             maintainRelayContract.TextToDisplayOnConsole = _textToDisplayOnConsole;
                             this.incrementSelectOperation();
                             this.addOperationHistory(maintainRelayContract.ServiceActionInfo);
                             azureRelaySender.fillRequest(maintainRelayContract);
                             response = azureRelaySender.SendMessage().GetAwaiter().GetResult();
                             if (response.IsSuccessStatusCode && response.StatusCode != System.Net.HttpStatusCode::Conflict)
                             {
                                 responseContract = azureRelaySender.contractFromResponseMessage(response) as IRicoKalkMaintainRelayResponseContract;

                                 enumerableList = responseContract.TblKalkSonstKzList;
                                 enumeratorList = enumerableList.GetEnumerator();
                                 while (enumeratorList.MoveNext())
                                 {
                                     TblKalkSonstKz tblKalkSonstKz  = enumeratorList.Current;
                                     priceListId = tblKalkSonstKz.KZ_ID;
                                 }
                             }
                         }
                     }
                 }
             }
         }
     }
     else
     {
         throw Error(response.ReasonPhrase);
     }
     return priceListId;
 }

